namespace sv_447edf200c954fd4ba3f5b7e23f0b4b7.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the latest low-stock alert count
/// and notifies all subscribers when the count changes.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever <see cref="LowStockCount"/> is updated.
    /// Subscribers that run on a non-Blazor thread must wrap
    /// StateHasChanged in <c>InvokeAsync</c>.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches the latest count and notifies all subscribers.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

