@@ -1,0 +1,88 @@
+@page "/dashboard"
+@rendermode InteractiveServer
+@inject InventoryAlertService AlertService
+@implements IDisposable
+
+<PageTitle>Warehouse Dashboard</PageTitle>
+
+<h1>Warehouse Dashboard</h1>
+
+<div class="card mb-4">
+    <div class="card-body">
+        <h5 class="card-title">
+            Current Site: @(Warehouse?.WarehouseName ?? "—")
+        </h5>
+        <p class="card-text">
+            @if (AlertService.LowStockCount > 0)
+            {
+                <span class="text-danger fw-bold">
+                    ⚠ @AlertService.LowStockCount item(s) below minimum stock level
+                </span>
+            }
+            else
+            {
+                <span class="text-success">✓ All stock levels are healthy</span>
+            }
+        </p>
+        <small class="text-muted">Refreshes every 10 seconds while this page is open.</small>
+    </div>
+</div>
+
+@code {
+    [CascadingParameter]
+    private WarehouseInfo? Warehouse { get; set; }
+
+    private string? _previousWarehouseId;
+    private CancellationTokenSource? _cts;
+    private Action? _handler;
+
+    protected override void OnInitialized()
+    {
+        _handler = () => InvokeAsync(StateHasChanged);
+        AlertService.OnChange += _handler;
+    }
+
+    protected override async Task OnParametersSetAsync()
+    {
+        var currentId = Warehouse?.WarehouseId;
+        if (currentId != _previousWarehouseId)
+        {
+            _previousWarehouseId = currentId;
+            // Warehouse changed — refresh immediately for the new site.
+            await AlertService.RefreshAsync(currentId ?? "WH-001");
+        }
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _cts = new CancellationTokenSource();
+            _ = PollAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollAsync(CancellationToken ct)
+    {
+        try
+        {
+            while (!ct.IsCancellationRequested)
+            {
+                await Task.Delay(TimeSpan.FromSeconds(10), ct);
+                await AlertService.RefreshAsync(Warehouse?.WarehouseId ?? "WH-001");
+            }
+        }
+        catch (OperationCanceledException)
+        {
+            // Expected on dispose — polling stops.
+        }
+    }
+
+    public void Dispose()
+    {
+        AlertService.OnChange -= _handler;
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
+

